package dev.hybridmail;
import android.app.Activity;
import androidx.credentials.*;
import androidx.credentials.exceptions.*;
import com.google.gson.*;
import java.nio.charset.StandardCharsets;
import java.security.*;
import java.util.*;
/** PRF is used only locally; no assertions, PRF outputs or settings are sent to a server. */
final class AndroidPasskeyPrf {
 interface Result{void ready(String credential,byte[] salt,byte[] prf);void failed(Exception e);}
 private String enrollmentMethod="not completed";
 String enrollmentMethod(){return enrollmentMethod;}
 private final Activity activity;private final CredentialManager manager;private final String origin;
 AndroidPasskeyPrf(Activity a)throws Exception{activity=a;manager=CredentialManager.create(a);var pkg=a.getPackageManager().getPackageInfo(a.getPackageName(),android.content.pm.PackageManager.GET_SIGNATURES);origin="android:apk-key-hash:"+PrfVault.b64(MessageDigest.getInstance("SHA-256").digest(pkg.signatures[0].toByteArray()));}
 static JsonObject object(String s){if(s.length()>65536)throw new SecurityException("Passkey response too large");return JsonParser.parseString(s).getAsJsonObject();}
 static void client(JsonObject response,String challenge,String origin,String type)throws Exception{var c=object(new String(PrfVault.decode(response.getAsJsonObject("response").get("clientDataJSON").getAsString()),StandardCharsets.UTF_8));if(!challenge.equals(c.get("challenge").getAsString())||!origin.equals(c.get("origin").getAsString())||!type.equals(c.get("type").getAsString())||(c.has("crossOrigin")&&c.get("crossOrigin").getAsBoolean()))throw new SecurityException("Passkey response context mismatch");}
 static byte[] result(JsonObject response,String credential,String challenge,String origin)throws Exception{client(response,challenge,origin,"webauthn.get");if(!"public-key".equals(response.get("type").getAsString())||!credential.equals(response.get("rawId").getAsString()))throw new SecurityException("Wrong passkey");byte[] auth=PrfVault.decode(response.getAsJsonObject("response").get("authenticatorData").getAsString());byte[] rp=MessageDigest.getInstance("SHA-256").digest(PrfVault.RP.getBytes(StandardCharsets.UTF_8));if(auth.length<37||!MessageDigest.isEqual(rp,Arrays.copyOf(auth,32))||(auth[32]&5)!=5)throw new SecurityException("Passkey user verification is required");var ext=response.getAsJsonObject("clientExtensionResults");if(ext==null||!ext.has("prf")||!ext.getAsJsonObject("prf").has("results"))throw new SecurityException("This credential provider did not return PRF output. Vault remains locked; no password fallback.");byte[] output=PrfVault.decode(ext.getAsJsonObject("prf").getAsJsonObject("results").get("first").getAsString());if(output.length!=32)throw new SecurityException("Invalid PRF output length");return output;}
 static byte[] creationResult(JsonObject response,String challenge,String origin)throws Exception {
  client(response,challenge,origin,"webauthn.create");if(!"public-key".equals(response.get("type").getAsString()))throw new SecurityException("Expected public-key credential");byte[] id=PrfVault.decode(response.get("rawId").getAsString());if(id.length==0||id.length>2048)throw new SecurityException("Invalid credential ID");
  var body=response.getAsJsonObject("response");byte[] auth=RegistrationCbor.authData(PrfVault.decode(body.get("attestationObject").getAsString()));
  byte[] rp=MessageDigest.getInstance("SHA-256").digest(PrfVault.RP.getBytes(StandardCharsets.UTF_8));if(auth.length<55||!MessageDigest.isEqual(rp,Arrays.copyOf(auth,32))||(auth[32]&0x45)!=0x45)throw new SecurityException("Registration requires user verification and attested credential data");int len=((auth[53]&255)<<8)|(auth[54]&255);if(len!=id.length||auth.length<=55+len||!MessageDigest.isEqual(id,Arrays.copyOfRange(auth,55,55+len)))throw new SecurityException("Registration credential mismatch");
  var ext=response.getAsJsonObject("clientExtensionResults");if(ext==null||!ext.has("prf"))return null;var prf=ext.getAsJsonObject("prf");if(prf.has("enabled")&&!prf.get("enabled").getAsBoolean())throw new SecurityException("Passkey provider does not support PRF");if(!prf.has("results"))return null;byte[] output=PrfVault.decode(prf.getAsJsonObject("results").get("first").getAsString());if(output.length!=32)throw new SecurityException("Invalid registration PRF output");return output;
 }
 void signalRemoved(String credential,java.util.function.Consumer<String> done){var j=new JsonObject();j.addProperty("rpId",PrfVault.RP);j.addProperty("credentialId",credential);signal(new SignalUnknownCredentialRequest(j.toString()),done);}
 void signalName(String userId,String name,java.util.function.Consumer<String> done){var j=new JsonObject();j.addProperty("rpId",PrfVault.RP);j.addProperty("userId",userId);j.addProperty("name",name);j.addProperty("displayName",name);signal(new SignalCurrentUserDetailsRequest(j.toString()),done);}
 private void signal(SignalCredentialStateRequest request,java.util.function.Consumer<String> done){if(android.os.Build.VERSION.SDK_INT<35){done.accept("Update the passkey in your provider manually; provider synchronization requires Android 15 or later.");return;}manager.signalCredentialStateAsync(request,activity::runOnUiThread,new CredentialManagerCallback<SignalCredentialStateResponse,androidx.credentials.exceptions.publickeycredential.SignalCredentialStateException>(){public void onResult(SignalCredentialStateResponse response){done.accept("Provider notified. It may update, hide or remove the passkey; check your provider to confirm.");}public void onError(androidx.credentials.exceptions.publickeycredential.SignalCredentialStateException e){done.accept("Local change saved. Provider synchronization was unavailable; update the passkey in your provider manually.");}});}
 void create(String name,java.util.function.Consumer<String> userIdReady,Result callback){
  discover(userIdReady,new Result(){public void ready(String credential,byte[] salt,byte[] output){enrollmentMethod="existing credential assertion";callback.ready(credential,salt,output);}public void failed(Exception e){
   new android.app.AlertDialog.Builder(activity).setTitle("No existing passkey selected").setMessage("No PRF-capable PQ Mail credential was selected. You can cancel without changing credentials, or explicitly create a new passkey.\n"+e.getMessage()).setNegativeButton("Cancel",(d,n)->callback.failed(new java.io.IOException("Passkey enrollment cancelled"))).setPositiveButton("Create new passkey",(d,n)->createNew(name,userIdReady,callback)).setOnCancelListener(d->callback.failed(new java.io.IOException("Passkey enrollment cancelled"))).show();
  }});
 }
 void discover(java.util.function.Consumer<String> userIdReady,Result callback){
  String challenge=PrfVault.b64(PrfVault.random(32));byte[] salt=PrfVault.random(32);var request=new JsonObject();request.addProperty("challenge",challenge);request.addProperty("rpId",PrfVault.RP);request.addProperty("userVerification","required");request.addProperty("timeout",120000);var eval=new JsonObject();eval.addProperty("first",PrfVault.b64(salt));var prf=new JsonObject();prf.add("eval",eval);var extensions=new JsonObject();extensions.add("prf",prf);request.add("extensions",extensions);
  manager.getCredentialAsync(activity,new GetCredentialRequest.Builder().addCredentialOption(new GetPublicKeyCredentialOption(request.toString())).build(),null,activity::runOnUiThread,new CredentialManagerCallback<GetCredentialResponse,GetCredentialException>(){
   public void onResult(GetCredentialResponse response){try{if(!(response.getCredential() instanceof PublicKeyCredential p))throw new SecurityException("Expected public-key credential");var json=object(p.getAuthenticationResponseJson());String id=json.get("rawId").getAsString();byte[] output=result(json,id,challenge,origin);var body=json.getAsJsonObject("response");userIdReady.accept(body.has("userHandle")&&!body.get("userHandle").isJsonNull()?body.get("userHandle").getAsString():"");callback.ready(id,salt,output);}catch(Exception e){callback.failed(e);}}
   public void onError(GetCredentialException e){callback.failed(new java.io.IOException("Existing passkey lookup did not complete: "+e.getType()));}
  });
 }
 private void createNew(String name,java.util.function.Consumer<String> userIdReady,Result callback){String challenge=PrfVault.b64(PrfVault.random(32));byte[] salt=PrfVault.random(32);var request=new JsonObject();request.addProperty("challenge",challenge);request.add("rp",object("{\"id\":\""+PrfVault.RP+"\",\"name\":\"PQ Mail vault\"}"));var user=new JsonObject();String userId=PrfVault.b64(PrfVault.random(32));user.addProperty("id",userId);user.addProperty("name",name);user.addProperty("displayName",name);request.add("user",user);request.add("pubKeyCredParams",JsonParser.parseString("[{\"type\":\"public-key\",\"alg\":-7},{\"type\":\"public-key\",\"alg\":-257}]"));request.add("authenticatorSelection",object("{\"residentKey\":\"required\",\"userVerification\":\"required\"}"));request.addProperty("attestation","none");request.addProperty("timeout",120000);var eval=new JsonObject();eval.addProperty("first",PrfVault.b64(salt));var prf=new JsonObject();prf.add("eval",eval);var extensions=new JsonObject();extensions.add("prf",prf);request.add("extensions",extensions);manager.createCredentialAsync(activity,new CreatePublicKeyCredentialRequest(request.toString()),null,activity::runOnUiThread,new CredentialManagerCallback<CreateCredentialResponse,CreateCredentialException>(){
 public void onResult(CreateCredentialResponse response){try{if(!(response instanceof CreatePublicKeyCredentialResponse r))throw new SecurityException("Expected passkey");var json=object(r.getRegistrationResponseJson());String id=json.get("rawId").getAsString();byte[] output=creationResult(json,challenge,origin);userIdReady.accept(userId);if(output!=null){enrollmentMethod="credential creation";callback.ready(id,salt,output);}else{enrollmentMethod="one assertion fallback";evaluate(id,salt,callback);}}catch(Exception e){callback.failed(e);}}
 public void onError(CreateCredentialException e){callback.failed(new java.io.IOException("Passkey creation failed: "+e.getType()));}});}
 void evaluate(String credential,byte[] salt,Result callback){String challenge=PrfVault.b64(PrfVault.random(32));var request=new JsonObject();request.addProperty("challenge",challenge);request.addProperty("rpId",PrfVault.RP);request.addProperty("userVerification","required");request.addProperty("timeout",120000);var allowed=new JsonObject();allowed.addProperty("type","public-key");allowed.addProperty("id",credential);var list=new JsonArray();list.add(allowed);request.add("allowCredentials",list);var eval=new JsonObject();eval.addProperty("first",PrfVault.b64(salt));var prf=new JsonObject();prf.add("eval",eval);var ext=new JsonObject();ext.add("prf",prf);request.add("extensions",ext);manager.getCredentialAsync(activity,new GetCredentialRequest.Builder().addCredentialOption(new GetPublicKeyCredentialOption(request.toString())).build(),null,activity::runOnUiThread,new CredentialManagerCallback<GetCredentialResponse,GetCredentialException>(){
 public void onResult(GetCredentialResponse response){try{if(!(response.getCredential() instanceof PublicKeyCredential c))throw new SecurityException("Expected passkey assertion");callback.ready(credential,salt,result(object(c.getAuthenticationResponseJson()),credential,challenge,origin));}catch(Exception e){callback.failed(e);}}
 public void onError(GetCredentialException e){callback.failed(new java.io.IOException("Passkey unlock failed: "+e.getType()));}});}
}
